Bash(powershell -NoProfile -Command "
\\$path = 'E:/UNITY GAME/类银河恶魔城/Assets/Scripts/QuestSystem/QuestManager.cs'
\\$content = [System.IO.File]::ReadAllText\(\\$path, [System.Text.Encoding]::UTF8\)

\\$old = '    public bool TryCompleteObjective'
\\$new = '    /// <summary>手动提交任务：检查进度 → 收集任务扣除物品 → 完成</summary>
    public bool SubmitQuest\(string questId\)
    {
        if \(!activeQuests.ContainsKey\(questId\)\)
            return false;

        var quest = GetQuestData\(questId\);
        if \(quest == null\)
            return false;

        var progress = activeQuests[questId];

        // 收集目标 → 检查并扣除背包物品
        for \(int i = 0; i < quest.objectives.Count; i++\)
        {
            if \(quest.objectives[i].type != ObjectiveType.Collect\)
                continue;

            int current = progress.objectiveProgress[i];
            int needed = quest.objectives[i].requiredCount - current;
            if \(needed <= 0\)
                continue;

            var inventory = FindFirstObjectByType<Inventory_Player>\(\);
            if \(inventory == null || CountItemsInInventory\(inventory, quest.objectives[i].targetId\) < needed\)
            {
                Debug.LogWarning\(\\"[任务] 背包中物品不足，无法提交\\"\);
                return false;
            }

            RemoveItemsFromInventory\(inventory, quest.objectives[i].targetId, needed\);
            progress.objectiveProgress[i] = quest.objectives[i].requiredCount;
            OnObjectiveUpdated?.Invoke\(questId, i, progress.objectiveProgress[i]\);
        }

        // 检查所有目标是否完成
        if \(!CheckQuestComplete\(quest, progress\)\)
        {
            Debug.Log\(\\"[任务] 目标尚未全部完成，无法提交\\"\);
            return false;
        }

        SetQuestReadyToClaim\(quest.questId\);
        Debug.Log\(\\$\\"[任务] 提交完成: {quest.questName}\\"\);
        return true;
    }

    public bool TryCompleteObjective'

\\$content = \\$content.Replace\(\\$old, \\$new\)

[System.IO.File]::WriteAllText\(\\$path, \\$content, [System.Text.Encoding]::UTF8\)
Write-Host 'added SubmitQuest'
")

